struct Wire {
    signal: bool,
    actions: Vec<fn(&mut Wire)>,
}

impl Wire {
    pub fn set_signal(&mut self, new_val: bool) {
        if self.signal != new_val {
            self.signal = new_val;
            // Infinite loop/reentrancy hazard if actions attempt to call set_signal back!
            for action in &self.actions {
                action(self);
            }
        }
    }
}
```

fix:
Collect the callbacks or state changes and execute them only after the struct has reached a stable, consistent state, or guard against reentrancy using execution flags.
