impl Wire {
    pub fn set_signal_deferred(&mut self, new_val: bool, queue: &mut EventQueue) {
        if self.signal != new_val {
            self.signal = new_val;
            for action in &self.actions {
                queue.push(*action); // Defer execution outside the state-transition lock
            }
        }
    }
}
